 meta=json.loads(f.with_suffix('.json').read_text(encoding='utf-8'));dst=out/(f.stem+'.wav');ambient=f.stem.startswith('ambient');m.convert(str(f),str(dst),'sfx',-24 if ambient else -16,-1.5,False,False);li,tp=m.out_loudness(str(dst));info=m.ffprobe(str(dst));assert tp<=-1.2
 clipped=meta['clean']['raw']['clipped'];items.append(dict(category='환경음' if ambient else '효과음',origin='새 생성 #567',title=f.stem,detail='SFX v2'+(' · 원본 CLIP '+str(clipped) if clipped else '')+(' · 루프 생성 / 이음새 청취 필요' if ambient else ''),path=dst.name,duration=info['dur']));qa.append(dict(file=dst.name,lufs=li,true_peak=tp,duration=info['dur'],raw_clipped=clipped))
